import{_ as e,c as t,o as i,ae as r}from"./chunks/framework.tbz6_956.js";const u=JSON.parse('{"title":"关于本书","description":"本书的目的、结构和阅读指南","frontmatter":{"title":"关于本书","description":"本书的目的、结构和阅读指南"},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),l={name:"guide/index.md"};function o(n,a,s,d,h,c){return i(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="关于本书" tabindex="-1">关于本书 <a class="header-anchor" href="#关于本书" aria-label="Permalink to &quot;关于本书&quot;">​</a></h1><h2 id="书籍简介" tabindex="-1">书籍简介 <a class="header-anchor" href="#书籍简介" aria-label="Permalink to &quot;书籍简介&quot;">​</a></h2><p>《中国历史智慧》是一本系统梳理中国数千年历史中蕴含的智慧与策略的著作。本书从传说时代的三皇五帝开始，一直到明清制度的兴衰，全面探讨了中国历史中的治国理念、管理智慧、哲学思想以及人生哲理。</p><h2 id="编写目的" tabindex="-1">编写目的 <a class="header-anchor" href="#编写目的" aria-label="Permalink to &quot;编写目的&quot;">​</a></h2><p>本书旨在：</p><ul><li>系统梳理中国历史中的智慧结晶</li><li>分析古代治国理政的成功经验</li><li>探讨传统思想对现代社会的启示</li><li>提供领导管理和人生修养的参考</li></ul><h2 id="内容结构" tabindex="-1">内容结构 <a class="header-anchor" href="#内容结构" aria-label="Permalink to &quot;内容结构&quot;">​</a></h2><p>全书共分为六个主要部分：</p><ol><li><strong>古代智慧的起源</strong> - 从三皇五帝到夏商周的文化积淀</li><li><strong>春秋战国的谋略</strong> - 百家争鸣与战略思想</li><li><strong>秦汉统一的智慧</strong> - 统一多民族国家的制度建设</li><li><strong>三国时代的权谋</strong> - 政治斗争与智慧博弈</li><li><strong>唐宋文化的繁荣</strong> - 文治盛世与思想高峰</li><li><strong>明清制度的兴衰</strong> - 制度演进与历史教训</li></ol><h2 id="阅读建议" tabindex="-1">阅读建议 <a class="header-anchor" href="#阅读建议" aria-label="Permalink to &quot;阅读建议&quot;">​</a></h2><p>建议读者按照章节顺序逐步阅读，也可以根据自己的兴趣选择特定章节。每个章节都包含了历史背景、主要人物、重要事件以及对现代的启示，方便读者全面理解。</p><h2 id="版权声明" tabindex="-1">版权声明 <a class="header-anchor" href="#版权声明" aria-label="Permalink to &quot;版权声明&quot;">​</a></h2><p>本书采用 CC-BY-SA-4.0 许可协议，鼓励分享和再创作，但请保持署名并以相同方式共享。</p>',13)])])}const _=e(l,[["render",o]]);export{u as __pageData,_ as default};
